    "excerpt": "里斯本常被称为“七座山丘之城”，但这个说法更像一个方便的别称，并没有一份固定名单。老城从特茹河边一路向上，陡街、石阶和观景台把街区连在一起，所以问路时，人们常说要“往上走”还是“往下走”。本地",
