      {
        "h": "Français",
        "p": "La Mouraria se trouve sous le château, à la lisière de la vieille ville médiévale. Son nom renvoie à la population maure qui vivait ici après la conquête chrétienne de 1147 ; le quartier est devenu un lieu de vie hors les murs, avec des rues étroites, de petits ateliers et une population mêlée. C'est aujourd'hui l'un des quartiers les plus multiculturels de Lisbonne, où vivent Portugais, Cap-Verdiens, Brésiliens et habitants sud-asiatiques.\n\nLa Mouraria est étroitement liée aux débuts du fado. La chanteuse Maria Severa, figure du XIXe siècle, appartient à la mémoire du quartier, et les maisons de fado comme les tascas modestes partagent encore ses ruelles. On y trouve aussi les Escadinhas de São Cristóvão, un escalier orné d'art urbain, et les fêtes de Santo António en juin. Les visiteurs doivent se rappeler qu'il s'agit d'un quartier habité : baissez la voix la nuit et traitez les ruelles comme la porte d'entrée de quelqu'un, non comme une scène."
      }
