    "id": "c007",
    "category": "lisboa",
    "kicker": "Lisboa e bairros",
    "title": "Bairro Alto, o bairro que acorda à noite",
    "zh": "上城：入夜才醒来的街区",
    "titleEn": "Bairro Alto, the neighbourhood that wakes at night",
    "titleFr": "Le Bairro Alto, le quartier qui s'éveille la nuit",
    "excerpt": "Bairro Alto 的意思是“上城”，但这个“上”是相对的：它在下城之上，却并不是里斯本最高的地方。这里十六世纪规划出的窄街呈网格状，白天很安静，有小店、小酒馆和晾在窗外的衣服。到了夜里，",
    "read": 4,
    "artWord": "noite",
    "sections": [
      {
        "h": "中文",
        "p": "Bairro Alto 的意思是“上城”，但这个“上”是相对的：它在下城之上，却并不是里斯本最高的地方。这里十六世纪规划出的窄街呈网格状，白天很安静，有小店、小酒馆和晾在窗外的衣服。到了夜里，街区完全变了样：人们来听法朵、吃便宜的晚饭，酒吧的客人挤到人行道上。\n\n上城的本地文化，核心是端着饮料站在街上、从小酒吧换到另一家、晚饭吃得很晚。酒馆里业余歌手唱的 fado vadio 也是这种生活的一部分。居民长期抱怨噪音，所以市政府制定了规则，限制部分区域的夜间噪音。想融入这里的游客，午夜后应压低谈话声，并记住这些街道同时也是别人的家。"
      },
      {
        "h": "English",
        "p": "Bairro Alto means 'upper neighbourhood', and its name is relative: it sits above the Baixa but is not one of Lisbon's highest points. Its grid of narrow streets was laid out in the sixteenth century, and by day it is quiet, with small shops, tascas and laundry lines. At night it changes completely, as people come for fado taverns, inexpensive restaurants and bars that spill onto the pavement.\n\nThe local culture of Bairro Alto is built on standing outside with a drink, moving from one small bar to another and eating late. Fado vadio, amateur fado sung in taverns, is part of that mixture. Residents have long complained about noise, and the city has introduced rules to limit late-night noise in parts of the quarter. A visitor who wants to fit in should keep conversation low after midnight and remember that the streets are also people's homes."
      },
      {
        "h": "Français",
        "p": "Bairro Alto signifie « quartier haut », un nom relatif : il domine la Baixa mais n'est pas le point le plus élevé de Lisbonne. Son quadrillage de ruelles étroites date du XVIe siècle ; le jour, l'endroit est calme, avec de petites boutiques, des tascas et du linge aux fenêtres. La nuit, tout change : on vient pour les tavernes de fado, les repas bon marché et les bars qui débordent sur le trottoir.\n\nLa culture locale du Bairro Alto repose sur le fait de boire debout, de passer d'un petit bar à l'autre et de dîner tard. Le fado vadio, chanté par des amateurs dans les tavernes, fait partie de ce mélange. Les habitants se plaignent depuis longtemps du bruit ; la ville a donc imposé des règles pour limiter le bruit nocturne dans certaines rues. Le visiteur qui veut s'intégrer baissera la voix après minuit et se souviendra que ces rues sont aussi des logements."
      }
    ],
