    "id": "c008",
    "category": "lisboa",
    "kicker": "Lisboa e bairros",
    "title": "O elétrico 28, Lisboa sobre carris",
    "zh": "28路电车：轨道上的里斯本",
    "titleEn": "Tram 28, Lisbon on rails",
    "titleFr": "Le tram 28, Lisbonne sur rails",
    "excerpt": "28路电车是里斯本最有名的 elétrico，这种黄色“Remodelado”电车吱吱作响地穿过老城。它的线路多年来有过变化，但通常连接 Martim Moniz 与 Campo de Our",
    "read": 4,
    "artWord": "elétrico",
    "sections": [
      {
        "h": "中文",
        "p": "28路电车是里斯本最有名的 elétrico，这种黄色“Remodelado”电车吱吱作响地穿过老城。它的线路多年来有过变化，但通常连接 Martim Moniz 与 Campo de Ourique 的 Prazeres，途经格拉萨、阿尔法玛、下城、希亚多和埃斯特雷拉。它不是博物馆里的展品，而是公共交通网络的一部分，本地人知道哪班车相对不挤，也会照常乘坐。\n\n坐一趟车，就像上一堂城市地理课。轨道爬上窄得不可思议的街道，擦过贴瓷砖的立面，转过急弯时车轮发出刺耳的响声。本地人把转弯时的尖叫声叫作 chiadeira，也常提醒游客避开高峰、看好包、把座位让给老人。有用的一句话是“o elétrico vai cheio”，意思是电车满了；夏天它常常确实如此。"
      },
      {
        "h": "English",
        "p": "Tram 28 is Lisbon's best-known elétrico, the yellow Remodelado tram that groans and squeals through the old city. Its route has changed over the years, but it normally connects Martim Moniz with Prazeres, in Campo de Ourique, passing Graça, Alfama, the Baixa, Chiado and Estrela. The tram is not a museum piece: it is a scheduled part of the public transport network, used by residents who know which trams are less crowded.\n\nThe ride is a lesson in city geography. The track climbs impossibly narrow streets, brushes past tiled facades and turns corners so tight that the wheels complain. Locals call the screech on curves 'chiadeira' and advise visitors to avoid rush hour, watch their bags and give up a seat to older passengers. A useful phrase is 'o elétrico vai cheio', meaning the tram is full; in summer, it often is."
      },
      {
        "h": "Français",
        "p": "Le tram 28 est l'elétrico le plus célèbre de Lisbonne : un Remodelado jaune qui grince et couine dans la vieille ville. Son parcours a changé au fil des ans, mais il relie normalement Martim Moniz à Prazeres, dans le quartier de Campo de Ourique, en passant par Graça, Alfama, la Baixa, le Chiado et Estrela. Ce n'est pas une pièce de musée : il fait partie du réseau de transports publics et les habitants l'empruntent en sachant quels trams sont les moins bondés.\n\nLe trajet est une leçon de géographie urbaine. La voie grimpe des rues incroyablement étroites, frôle des façades couvertes d'azulejos et négocie des virages si serrés que les roues protestent. Les habitants appellent ce grincement « chiadeira » et conseillent aux visiteurs d'éviter l'heure de pointe, de surveiller leurs sacs et de laisser leur place aux personnes âgées. Une phrase utile : « o elétrico vai cheio », le tram est plein ; en été, c'est souvent le cas."
      }
    ],
