    "id": "c009",
    "category": "lisboa",
    "kicker": "Lisboa e bairros",
    "title": "O Tejo, o rio que parece mar",
    "zh": "特茹河：像海一样的河",
    "titleEn": "The Tejo, the river that feels like the sea",
    "titleFr": "Le Tejo, ce fleuve qui ressemble à la mer",
    "excerpt": "里斯本面朝特茹河。这条河发源于西班牙，穿过葡萄牙后注入大西洋。到了里斯本附近，河面展宽，形成宽阔的河口，本地人叫它 o mar da palha——“稻草海”，可能是因为含泥沙的河水在某些光线",
    "read": 4,
    "artWord": "Tejo",
    "sections": [
      {
        "h": "中文",
        "p": "里斯本面朝特茹河。这条河发源于西班牙，穿过葡萄牙后注入大西洋。到了里斯本附近，河面展宽，形成宽阔的河口，本地人叫它 o mar da palha——“稻草海”，可能是因为含泥沙的河水在某些光线下呈这种颜色。它不是海，却有潮汐、水流和一条让城市显得开阔的地平线。\n\n河岸已经织进日常生活。人们说“vou ver o rio”——去看河——意思可能是散步、日落时喝杯啤酒，或只是安静一会儿。被称作 cacilheiros 的渡轮开往南岸的卡西利亚斯，里斯本人会去那边吃海鲜，再回头望城市。河流也划出社会地理：北岸是里斯本，而“a outra margem”（对岸）有自己的城镇和身份。天气晴朗时，基督像从对岸俯视着这里。"
      },
      {
        "h": "English",
        "p": "Lisbon faces the Tejo, the long river rising in Spain and reaching the Atlantic through Portugal. At the city the river widens into a broad estuary, so wide that locals call it o mar da palha, the 'sea of straw', perhaps because of the colour of its silt-laden water at certain lights. It is not the ocean, but it has tides, currents and a horizon that makes the city feel open.\n\nThe riverfront is woven into daily life. People say 'vou ver o rio' (I'm going to look at the river) and mean a walk, a beer at sunset or a moment of quiet. Ferries, known as cacilheiros, cross to Cacilhas on the south bank, where Lisboetas go for seafood and a view back at the city. The river also marks social geography: the north bank is Lisbon, while 'a outra margem' has its own towns and identity. On clear days, the Cristo Rei statue watches from the far side."
      },
      {
        "h": "Français",
        "p": "Lisbonne fait face au Tejo, le long fleuve né en Espagne qui rejoint l'Atlantique par le Portugal. Devant la ville, il s'élargit en un vaste estuaire, si large que les habitants l'appellent o mar da palha, la « mer de paille », peut-être à cause de la couleur de son eau limoneuse sous certaines lumières. Ce n'est pas l'océan, mais il a des marées, des courants et un horizon largement ouvert.\n\nLes quais font partie de la vie quotidienne. On dit « vou ver o rio » (je vais voir le fleuve) pour une promenade, une bière au coucher du soleil ou un moment calme. Les ferries, appelés cacilheiros, traversent vers Cacilhas, sur la rive sud, où les Lisboètes vont manger du poisson et regarder la ville. Le fleuve dessine aussi une géographie sociale : la rive nord, c'est Lisbonne, tandis que « a outra margem » a ses propres villes et son identité. Par temps clair, le Cristo Rei veille depuis l'autre côté."
      }
    ],
