    "id": "c010",
    "category": "lisboa",
    "kicker": "Lisboa e bairros",
    "title": "Sintra, a escapadela romântica de Lisboa",
    "zh": "辛特拉：里斯本的浪漫一日游",
    "titleEn": "Sintra, Lisbon's romantic day trip",
    "titleFr": "Sintra, l'escapade romantique de Lisbonne",
    "excerpt": "辛特拉位于里斯本以西的山中，从罗西奥车站坐火车就能方便到达。整座城镇是联合国教科文组织认定的文化景观：宫殿和花园围绕历史中心生长，凉爽多雾的微气候让这里的植物显得比干燥的里斯本平原更偏北方。十",
    "read": 5,
    "artWord": "palácio",
    "sections": [
      {
        "h": "中文",
        "p": "辛特拉位于里斯本以西的山中，从罗西奥车站坐火车就能方便到达。整座城镇是联合国教科文组织认定的文化景观：宫殿和花园围绕历史中心生长，凉爽多雾的微气候让这里的植物显得比干燥的里斯本平原更偏北方。十九世纪，费尔南多二世国王把一座修道院的废墟改造成色彩鲜艳的佩纳宫，刻意用混合的建筑风格营造浪漫效果。\n\n一日游最好有取舍。佩纳宫、摩尔人城堡、雷加莱拉庄园和辛特拉王宫分布较散，游客通常选两处，而不是试图全部看完。记得穿适合陡坡的鞋，夏天也带一件薄外套，并提前买好分时段门票。离开前可以尝一个 travesseiro——一种杏仁奶油馅、枕头形状的小点心，是当地特色，配咖啡正好。"
      },
      {
        "h": "English",
        "p": "Sintra sits in the hills west of Lisbon and is easy to reach by train from Rossio station. The town is a UNESCO Cultural Landscape: its palaces and gardens grew around a historic centre, and the cool, misty microclimate makes the vegetation feel more northern than the dry Lisbon plain. In the nineteenth century, King Ferdinand II turned the ruins of a monastery into the colourful Pena Palace, mixing architectural styles in a deliberately romantic way.\n\nA day trip works best with a plan. The main sights, Pena Palace, the Moorish Castle, Quinta da Regaleira and the National Palace, are spread out, so visitors often choose two rather than trying to see everything. Wear shoes for steep paths, carry a light jacket even in summer, and buy timed tickets in advance. Before leaving, try a travesseiro, a small pillow-shaped pastry filled with almond cream, a local speciality that pairs well with a coffee."
      },
      {
        "h": "Français",
        "p": "Sintra se niche dans les collines à l'ouest de Lisbonne et se rejoint facilement en train depuis le Rossio. La ville est un paysage culturel inscrit à l'UNESCO : ses palais et jardins se sont développés autour d'un centre historique, et le microclimat frais et brumeux rend la végétation plus nordique que celle de la plaine sèche de Lisbonne. Au XIXe siècle, le roi Ferdinand II a transformé les ruines d'un monastère en palais de Pena coloré, mêlant les styles architecturaux de façon volontairement romantique.\n\nUne excursion demande des choix. Les principaux sites, le palais de Pena, le château maure, la Quinta da Regaleira et le palais national, sont dispersés : les visiteurs en choisissent souvent deux plutôt que tout voir. Prévoyez des chaussures pour les sentiers raides, une veste légère même en été et des billets horodatés à l'avance. Avant de partir, goûtez un travesseiro, une petite pâtisserie en forme d'oreiller fourrée à la crème d'amande, qui accompagne bien un café."
      }
    ],
