    "id": "c011",
    "category": "gastronomia",
    "kicker": "Gastronomia",
    "title": "Bacalhau, o fiel amigo",
    "zh": "鳕鱼：忠诚的朋友",
    "titleEn": "Bacalhau, the loyal friend",
    "titleFr": "Le bacalhau, fidèle ami",
    "excerpt": "bacalhau 是葡萄牙的盐渍干鳕鱼，不是鲜鱼，而是一种保存食物。鳕鱼在寒冷的北大西洋捕获，剖开、厚厚抹盐、风干，直到肉质紧实、咸味浓重；葡萄牙渔船过去常在纽芬兰外的大浅滩捕捞。下锅前要泡在",
    "read": 4,
    "artWord": "bacalhau",
    "sections": [
      {
        "h": "中文",
        "p": "bacalhau 是葡萄牙的盐渍干鳕鱼，不是鲜鱼，而是一种保存食物。鳕鱼在寒冷的北大西洋捕获，剖开、厚厚抹盐、风干，直到肉质紧实、咸味浓重；葡萄牙渔船过去常在纽芬兰外的大浅滩捕捞。下锅前要泡在冷水里一到两天，中间多次换水，把盐分泡出来。\n\n做法按地区分家：波尔图人认 à Gomes de Sá，和土豆、洋葱、鸡蛋、橄榄一起烤；里斯本人认 à Brás，把鳕鱼撕碎，拌细土豆丝和鸡蛋炒；贝拉地区则用橄榄油和压碎的土豆烤成 à lagareiro。圣诞夜，它常只是配卷心菜和土豆白煮上桌。在餐馆点菜，问清是 lombo 还是 posta，不同部位的口感和咸度差别很大，而且一份通常够两个人分。"
      },
      {
        "h": "English",
        "p": "Bacalhau is Portugal's salted, dried cod: a cured ingredient rather than a fresh fish. Cod caught in the cold North Atlantic is split, heavily salted and dried until firm and deeply savoury; Portuguese boats once worked the Grand Banks off Newfoundland. Before cooking it is soaked in cold water for a day or more, the water changed several times, to draw out the salt.\n\nRecipes divide the country. Porto claims bacalhau à Gomes de Sá, baked with potatoes, onion, egg and olives; Lisbon claims à Brás, shredded cod with matchstick potatoes and egg; the Beira roasts it à lagareiro, with olive oil and crushed potatoes. At Christmas Eve supper it is often simply boiled with cabbage and potatoes. In a restaurant, ask whether you are ordering lombo or posta, since the cut changes texture and salt, and expect a portion meant for sharing."
      },
      {
        "h": "Français",
        "p": "Le bacalhau, c'est la morue salée et séchée du Portugal : un produit de conservation, pas un poisson frais. Pêchée dans l'Atlantique Nord, la morue est fendue, salée, puis séchée jusqu'à devenir ferme et savoureuse ; les bateaux portugais travaillaient autrefois les bancs de Terre-Neuve. Avant cuisson, on la dessale dans l'eau froide pendant un jour ou plus, en changeant l'eau plusieurs fois.\n\nLes recettes divisent le pays. Porto revendique le bacalhau à Gomes de Sá, cuit avec pommes de terre, oignon, œuf et olives ; Lisbonne, l'à Brás, morue effilochée, frites allumettes et œufs ; la Beira le rôtit à lagareiro, à l'huile d'olive, avec des pommes de terre écrasées. À la veille de Noël, il est souvent servi simplement bouilli avec du chou et des pommes de terre. Au restaurant, demandez si vous prenez du lombo ou une posta, car la découpe change la texture et le sel, et comptez une portion pour deux."
      }
    ],
    "tips": []
