    "id": "c022",
    "category": "fado",
    "kicker": "Fado e música",
    "title": "As casas de fado de Lisboa",
    "zh": "里斯本的法朵之家",
    "titleEn": "Lisbon's fado houses",
    "titleFr": "Les maisons de fado de Lisbonne",
    "excerpt": "法朵之家是里斯本的小餐馆，人们在里面吃饭、喝酒、听现场法朵。这类场所多集中在阿尔法玛、莫拉里亚、巴伊鲁阿尔图和阿茹达。房间狭小，桌子紧挨；歌手和吉他手一夜之间穿梭于数家餐馆，每家唱上几首。晚餐",
    "read": 4,
    "artWord": "noite",
    "sections": [
      {
        "h": "中文",
        "p": "法朵之家是里斯本的小餐馆，人们在里面吃饭、喝酒、听现场法朵。这类场所多集中在阿尔法玛、莫拉里亚、巴伊鲁阿尔图和阿茹达。房间狭小，桌子紧挨；歌手和吉他手一夜之间穿梭于数家餐馆，每家唱上几首。晚餐通常八点左右开始，音乐更晚。\n\n有些名店如法朵俱乐部和曾为小教堂的梅萨德弗拉德斯；另一些只是小酒馆，业余爱好者在那里唱“流浪法朵”。最好提前订位，并准备付入场费；歌声一起就请压低嗓音。这里的气氛私密而非戏剧化，重点是在近处听人声和葡萄牙吉他。"
      },
      {
        "h": "English",
        "p": "A casa de fado is a small Lisbon restaurant where people eat, drink and listen to live fado. Most are in Alfama, Mouraria, Bairro Alto and Ajuda. The rooms are tiny and the tables close together; singers and guitarists move between houses in the same night, performing a few songs at each. Dinner usually starts around eight, the music later.\n\nSome houses are famous, such as Clube de Fado and Mesa de Frades, once a chapel. Others are simple taverns where amateurs sing fado vadio. Reserve ahead, expect a cover charge, and keep your voice down when the singing starts. The atmosphere is intimate rather than theatrical: the point is to hear the voice and the guitarra up close."
      },
      {
        "h": "Français",
        "p": "Une casa de fado est un petit restaurant lisboète où l'on mange, boit et écoute du fado en direct. La plupart se trouvent dans l'Alfama, la Mouraria, le Bairro Alto et Ajuda. Les salles sont minuscules et les tables serrées ; chanteurs et guitaristes passent de maison en maison dans la même soirée, donnant quelques chansons à chaque fois. Le dîner commence vers vingt heures, la musique plus tard.\n\nCertaines maisons sont célèbres, comme le Clube de Fado ou la Mesa de Frades, installée dans une ancienne chapelle. D'autres sont de simples tavernes où des amateurs chantent le fado vadio. Réservez à l'avance, attendez-vous à un droit d'entrée et baissez la voix quand le chant commence. L'ambiance est intime plutôt que théâtrale : l'essentiel est d'entendre la voix et la guitarra de près."
      }
    ],
