    "id": "c023",
    "category": "fado",
    "kicker": "Fado e música",
    "title": "O fado de Coimbra",
    "zh": "科英布拉法朵",
    "titleEn": "Coimbra fado",
    "titleFr": "Le fado de Coimbra",
    "excerpt": "科英布拉法朵是大学之城的歌声。它十九世纪在学生中诞生，至今主要由男性演唱，歌者常穿科英布拉学术制服的黑斗篷。演出在夜间进行，地点是老大学和旧主教座堂周围的街巷广场，以及城里的法朵之家。它与科英",
    "read": 3,
    "artWord": "capa",
    "sections": [
      {
        "h": "中文",
        "p": "科英布拉法朵是大学之城的歌声。它十九世纪在学生中诞生，至今主要由男性演唱，歌者常穿科英布拉学术制服的黑斗篷。演出在夜间进行，地点是老大学和旧主教座堂周围的街巷广场，以及城里的法朵之家。它与科英布拉的学术传统紧密相连，毕业季的告别尤其动人。\n\n它的音色与里斯本不同：科英布拉吉他更小、更明亮，唱法含蓄，接近小夜曲。歌曲唱学生生活、爱情与离别，《告别叙事曲》常为一夜收尾。在科英布拉，静默是演出的一部分：听众不说话，等一首唱完才鼓掌。"
      },
      {
        "h": "English",
        "p": "Coimbra fado is the song of the university city. It was born among students in the nineteenth century and is still sung mainly by men, often wearing the black cape of Coimbra's academic uniform. Performances happen at night, in the streets and squares around the old university and the Sé Velha, and in the city's fado houses.\n\nIts sound differs from Lisbon's: the guitarra coimbrã is smaller and brighter, and the singing is restrained, closer to a serenade. The songs speak of student life, love and farewell, and the Balada da Despedida closes many nights. In Coimbra, silence is part of the performance; the audience listens without talking, and applause comes after the song."
      },
      {
        "h": "Français",
        "p": "Le fado de Coimbra est le chant de la ville universitaire. Né parmi les étudiants au XIXe siècle, il est encore interprété surtout par des hommes, souvent vêtus de la cape noire de l'uniforme académique. Les prestations ont lieu la nuit, dans les rues et les places autour de l'ancienne université et de la Sé Velha, ainsi que dans les maisons de fado de la ville.\n\nSon timbre diffère de celui de Lisbonne : la guitarra coimbrã est plus petite et plus claire, et le chant est retenu, proche d'une sérénade. Les chansons parlent de la vie étudiante, de l'amour et des adieux, et la Balada da Despedida clôt souvent les soirées. À Coimbra, le silence fait partie du spectacle ; on écoute sans parler et on applaudit après la chanson."
      }
    ],
