    "id": "c024",
    "category": "fado",
    "kicker": "Fado e música",
    "title": "A guitarra portuguesa",
    "zh": "葡萄牙吉他",
    "titleEn": "The Portuguese guitar",
    "titleFr": "La guitarra portuguesa",
    "excerpt": "葡萄牙吉他是赋予法朵标志性音色的乐器。它源自英国的西特琴，这种金属弦乐器于十八世纪传入葡萄牙。它有十二根钢丝弦，分成六组双弦，琴身呈梨形，音色温暖而略带鼻音，能穿透整个嘈杂的房间。 演奏者用拇",
    "read": 4,
    "artWord": "guitarra",
    "sections": [
      {
        "h": "中文",
        "p": "葡萄牙吉他是赋予法朵标志性音色的乐器。它源自英国的西特琴，这种金属弦乐器于十八世纪传入葡萄牙。它有十二根钢丝弦，分成六组双弦，琴身呈梨形，音色温暖而略带鼻音，能穿透整个嘈杂的房间。\n\n演奏者用拇指和食指的指甲拨弦，快速交替；里斯本琴较大，科英布拉琴较小、音更高。在法朵三重奏中，它与木吉他和低音吉他一起为人声伴奏。卡洛斯·帕雷德斯使它成为独奏乐器，今日里卡多·罗沙等演奏家延续着这一传统。它也是法朵中最容易辨认的声音。"
      },
      {
        "h": "English",
        "p": "The guitarra portuguesa is the instrument that gives fado its signature sound. It descends from the English cittern, a wire-strung instrument that reached Portugal in the eighteenth century. It has twelve steel strings in six double courses, a pear-shaped body and a warm, slightly nasal tone that cuts through even a crowded room.\n\nIt is played with the nails of the thumb and index finger, in rapid alternating patterns; the Lisbon model is larger, the Coimbra model smaller and higher. In a fado trio it accompanies the voice alongside the viola and the viola baixo. Carlos Paredes made it a solo instrument, and players such as Ricardo Rocha carry that legacy today."
      },
      {
        "h": "Français",
        "p": "La guitarra portuguesa est l'instrument qui donne au fado sa sonorité reconnaissable. Elle descend du cistre anglais, un instrument à cordes métalliques arrivé au Portugal au XVIIIe siècle. Elle possède douze cordes d'acier groupées en six chœurs doubles, un corps en forme de poire et un timbre chaud, légèrement nasillard, qui traverse même une salle bruyante.\n\nOn en joue avec les ongles du pouce et de l'index, par des motifs alternés très rapides ; le modèle de Lisbonne est plus grand, celui de Coimbra plus petit et plus aigu. Dans un trio de fado, elle accompagne la voix avec la viola et la viola baixo. Carlos Paredes en a fait un instrument soliste, et des interprètes comme Ricardo Rocha poursuivent cet héritage."
      }
    ],
    "tips": []
