    "category": "festas",
    "kicker": "Festas e tradições",
    "title": "São João no Porto",
    "zh": "波尔图的圣若昂节",
    "titleEn": "São João in Porto",
    "titleFr": "São João à Porto",
    "excerpt": "6月23日夜里，波尔图庆祝城市主保圣人圣若昂，这是葡萄牙最奔放的街头节庆之一。人们与家人朋友聚在里贝拉、丰塔伊尼亚斯等老城区，吃烤沙丁鱼、烤甜椒和玉米面包，喝酒，在露天舞会上跳舞。午夜前后，杜",
    "read": 4,
    "artWord": "martelo",
    "sections": [
      {
        "h": "中文",
        "p": "6月23日夜里，波尔图庆祝城市主保圣人圣若昂，这是葡萄牙最奔放的街头节庆之一。人们与家人朋友聚在里贝拉、丰塔伊尼亚斯等老城区，吃烤沙丁鱼、烤甜椒和玉米面包，喝酒，在露天舞会上跳舞。午夜前后，杜罗河上空放起烟花，狂欢一直持续到天亮。\n\n最有名的习俗带点恶作剧：人们用塑料小锤或长条韭葱轻轻敲别人的头。这只是玩笑，轻轻一下就够了，不该用力。街上还会看到彩色装饰。建议穿舒适的鞋，做好人挤人的准备，并把贵重物品收好。如果有人举起小锤，笑一笑、低下头配合就好。说一句“Viva o São João!”（圣若昂万岁），加入这场一年一度的狂欢吧。"
      },
      {
        "h": "English",
        "p": "On the night of 23 June, Porto celebrates São João, the city's patron saint, with one of Portugal's most exuberant street parties. Families and friends gather in Ribeira, Fontaínhas and other old neighbourhoods to eat grilled sardines, roast peppers and broa, drink wine and dance at open-air balls. Around midnight, fireworks light up the Douro, and the party continues until dawn.\n\nThe best-known custom is playful: people tap strangers lightly on the head with plastic hammers or long leeks. It is done in fun, but a gentle tap is enough; nobody is meant to hit hard. You will also see colourful decorations in the streets. Wear comfortable shoes, expect crowds and keep valuables close. If someone raises a hammer, smile and lower your head. Say «Viva o São João!» and join in."
      },
      {
        "h": "Français",
        "p": "Dans la nuit du 23 juin, Porto célèbre São João, son saint patron, lors de l'une des fêtes de rue les plus exubérantes du Portugal. Familles et amis se retrouvent à Ribeira, Fontaínhas et dans d'autres vieux quartiers pour manger des sardines grillées, des poivrons rôtis et du broa, boire du vin et danser aux bals en plein air. Vers minuit, un feu d'artifice illumine le Douro, et la fête continue jusqu'à l'aube.\n\nLa coutume la plus célèbre est espiègle : on frappe doucement la tête des passants avec des marteaux en plastique ou de longs poireaux. C'est un jeu, mais un petit coup suffit ; personne ne doit frapper fort. Les rues sont aussi décorées de couleurs vives. Portez des chaussures confortables, attendez-vous à la foule et gardez vos objets de valeur près de vous. Si quelqu'un lève son marteau, souriez et baissez la tête. Dites « Viva o São João ! » et joignez-vous à la fête."
      }
    ],
