    "title": "Carnaval em Portugal",
    "zh": "葡萄牙狂欢节",
    "titleEn": "Carnaval in Portugal",
    "titleFr": "Le Carnaval au Portugal",
    "excerpt": "狂欢节是大斋期前葡萄牙最后的盛大狂欢。日期按复活节推算，每年不同：主要庆祝活动从周六持续到“肥美星期二”，就在圣灰星期三之前。托里什韦德拉什以讽刺花车和化装人潮闻名；洛莱有彩色游行；奥瓦尔以充",
    "read": 3,
    "artWord": "entrudo",
    "sections": [
      {
        "h": "中文",
        "p": "狂欢节是大斋期前葡萄牙最后的盛大狂欢。日期按复活节推算，每年不同：主要庆祝活动从周六持续到“肥美星期二”，就在圣灰星期三之前。托里什韦德拉什以讽刺花车和化装人潮闻名；洛莱有彩色游行；奥瓦尔以充满活力的狂欢节著称；东北部波登塞的“Caretos”身穿彩色羊毛服、戴金属面具、腰系牛铃，这一传统已列入联合国教科文组织非物质文化遗产名录。\n\n吃也是狂欢节的一部分。面包店会卖“malassadas”“filhoses”和“sonhos”等油炸甜点，适合大斋期前享用。若去参加，先查节目表，尽早订交通，北部夜晚可能很冷。各地都欢迎化装，但气氛从家庭游行到喧闹派对都有。给戴面具的团体拍照前先询问；到了圣灰星期三，狂欢会戛然而止。"
      },
      {
        "h": "English",
        "p": "Carnaval is Portugal's last big party before Lent. Its dates change each year because they depend on Easter: the main celebrations run from the Saturday to Shrove Tuesday, just before Ash Wednesday. Towns celebrate in very different ways. Torres Vedras is famous for satirical floats and crowds in costume; Loulé, in the Algarve, holds a colourful parade; Ovar is known for its energetic Carnival; and in Podence, in the north-east, masked revellers wear colourful woolen suits, metal masks and cowbells as Caretos, a tradition recognised by UNESCO.\n\nFood is part of the fun. Bakeries sell malassadas, filhoses and sonhos, fried dough sweets that are especially popular before fasting begins. If you go, check the local programme, book transport early and expect cold nights in the north. Costumes are welcome everywhere, but the tone varies from family-friendly parades to noisy street parties. Ask before photographing masked groups, and remember that Ash Wednesday brings the party to an abrupt end."
      },
      {
        "h": "Français",
        "p": "Le Carnaval est la dernière grande fête portugaise avant le carême. Ses dates varient avec Pâques : les célébrations principales vont du samedi au mardi gras, juste avant le mercredi des Cendres. Les styles varient beaucoup. Torres Vedras est célèbre pour ses chars satiriques et ses foules costumées ; Loulé, en Algarve, organise un défilé coloré ; Ovar est connue pour son carnaval énergique ; à Podence, dans le nord-est, les fêtards masqués portent des costumes de laine colorés, des masques de métal et des cloches, les Caretos, une tradition reconnue par l'UNESCO.\n\nLa fête se mange aussi. Les pâtisseries vendent des malassadas, des filhoses et des sonhos, beignets frits appréciés avant le jeûne. Consultez le programme local, réservez tôt et prévoyez des nuits froides dans le nord. Les costumes sont bienvenus, mais l'ambiance va des défilés familiaux aux fêtes bruyantes. Demandez avant de photographier les groupes masqués ; le mercredi des Cendres clôt la fête."
      }
    ],
