    "kicker": "Festas e tradições",
    "title": "Páscoa e Semana Santa",
    "zh": "复活节与圣周",
    "titleEn": "Easter and Holy Week",
    "titleFr": "Pâques et la Semaine sainte",
    "excerpt": "圣周是葡萄牙天主教日历中最庄重的时期，从圣枝主日开始，到复活节星期日结束。在布拉加，游行会连续几个夜晚穿过历史城区；耶稣受难日的场面尤其震撼，人群安静无声，手持蜡烛，护送“主之葬礼”游行。其他",
    "read": 4,
    "artWord": "folar",
    "sections": [
      {
        "h": "中文",
        "p": "圣周是葡萄牙天主教日历中最庄重的时期，从圣枝主日开始，到复活节星期日结束。在布拉加，游行会连续几个夜晚穿过历史城区；耶稣受难日的场面尤其震撼，人群安静无声，手持蜡烛，护送“主之葬礼”游行。其他地方的教堂会在圣周四举行濯足礼，在耶稣受难日举行朝拜十字架礼。耶稣受难日和复活节星期日，不少商铺会关门。\n\n复活节也是家庭节日。传统甜点是“folar”，一种常带肉桂香味的甜面包，教父母可能会送给教子女。家人聚在一起吃午饭，通常有烤羊肉或烤山羊肉，并举杯喝葡萄酒或起泡酒。可以学说“Boa Páscoa!”或“Feliz Páscoa!”（复活节快乐）。若参观游行，穿着宜庄重，祈祷时保持安静，不要挡住队伍。节日前几天的气氛偏沉静，而不是热闹。"
      },
      {
        "h": "English",
        "p": "Holy Week, Semana Santa, is the most solemn period in the Portuguese Catholic calendar. It begins on Palm Sunday and culminates on Easter Sunday. In Braga, processions move through the historic centre on several nights; Good Friday is especially striking, with silent crowds, candles and the burial procession of the Lord. Churches elsewhere hold the washing of the feet on Maundy Thursday and the veneration of the cross on Good Friday. Many businesses close both days.\n\nEaster is also a family holiday. The traditional sweet is folar, an enriched bread often flavoured with cinnamon; godparents may give one to their godchildren. Families gather for lunch, often roast lamb or kid goat, and toast with a glass of wine or sparkling wine. Practise the greetings «Boa Páscoa!» or «Feliz Páscoa!». If you visit a procession, dress respectfully, stay silent during prayers and do not block the route. The mood is reflective rather than festive, especially before Sunday."
      },
      {
        "h": "Français",
        "p": "La Semaine sainte est la période la plus solennelle du calendrier catholique. Elle commence le dimanche des Rameaux et s'achève le dimanche de Pâques. À Braga, des processions traversent le centre historique plusieurs soirs ; le Vendredi saint, avec ses foules silencieuses et ses cierges, culmine dans la procession de l'Enterrement du Seigneur. Ailleurs, on célèbre le lavement des pieds le Jeudi saint et la vénération de la croix le Vendredi saint. Beaucoup de commerces ferment ces jours-là.\n\nPâques est aussi une fête familiale. La pâtisserie traditionnelle est le folar, un pain sucré, souvent parfumé à la cannelle ; les parrains et marraines peuvent en offrir à leurs filleuls. Les familles déjeunent souvent d'agneau ou de chevreau rôti et trinquent avec du vin ou du mousseux. Dites « Boa Páscoa ! » ou « Feliz Páscoa ! ». Si vous assistez à une procession, habillez-vous sobrement, restez silencieux pendant les prières et ne bloquez pas le passage. L'ambiance est recueillie plutôt que festive, surtout avant le dimanche."
      }
    ],
