        "h": "Français",
        "p": "La Fête des fleurs de Madère transforme Funchal en jardin, généralement entre la fin avril et la fin mai. Les dates changent chaque année : consultez le programme. Le centre se couvre de tapis et d'installations florales, dans un parfum de fleurs fraîches. L'un des premiers événements est le Muro da Esperança, le Mur de l'espérance : des enfants déposent des fleurs sur ce mur pour la paix. Pendant les défilés, la parade allégorique apporte des chars, des costumes et de la musique dans les rues principales.\n\nLa fête célèbre le climat doux de Madère et sa tradition horticole. Balcons et vitrines se couvrent de fleurs, et le Mercado dos Lavradores met en valeur fleurs et produits locaux. Partez tôt, chaussez-vous confortablement et prévoyez un temps changeant. Le défilé est couru : arrivez tôt. Admirez les compositions, mais ne cueillez pas de fleurs et n'entrez pas dans les jardins privés. Photographiez couleurs et parfums, mais laissez les fleurs à tout le monde."
