    "title": "Santos Populares e arraiais",
    "zh": "民间圣徒节与露天街区派对",
    "titleEn": "Santos Populares and Arraiais",
    "titleFr": "Les Santos Populares et les arraiais",
    "excerpt": "六月是“Santos Populares”（民间圣徒节）的月份：6月13日圣安东尼奥、6月24日圣若昂、6月29日圣佩德罗。葡萄牙各地街区都会搭起“arraiais”露天派对，摆出小吃摊，挂上",
    "read": 4,
    "artWord": "arraial",
    "sections": [
      {
        "h": "中文",
        "p": "六月是“Santos Populares”（民间圣徒节）的月份：6月13日圣安东尼奥、6月24日圣若昂、6月29日圣佩德罗。葡萄牙各地街区都会搭起“arraiais”露天派对，摆出小吃摊，挂上纸饰，放起音乐。里斯本的阿尔法玛、格拉萨和比卡等街区很有名，波尔图的里贝拉和丰塔伊尼亚斯也很热闹。气氛轻松，人们吃喝、大声聊天、跳舞到深夜。\n\n“arraial”是观察葡萄牙人社交方式的好地方。到柜台点单、当场付钱，喝完把杯子送回摊位。烤沙丁鱼、bifanas（猪肉三明治）和绿菜汤是常见食物，可以站着吃，也可以坐在长桌旁。音乐从流行歌曲到民谣乐队、DJ都有。有人邀请你跳舞就加入，但不要未经询问就拍别人。傍晚时段适合家庭，越晚越喧闹。若住在居民区，不妨备一副耳塞，音乐往往持续到很晚。"
      },
      {
        "h": "English",
        "p": "June is the month of the Santos Populares, the popular saints: Santo António on 13 June, São João on 24 June and São Pedro on 29 June. Across Portugal, neighbourhoods organise arraiais, informal street parties with food stalls, paper decorations and music. Lisbon's arraiais are famous in Alfama, Graça and Bica; Porto's are lively in Ribeira and Fontaínhas. The atmosphere is relaxed: people eat, drink, talk loudly and dance until late.\n\nThe arraial is a good place to observe Portuguese sociability. Order at the counter, pay as you go and return your glass to the stall. Grilled sardines, bifanas and caldo verde are typical, and you can eat standing or at long shared tables. Music ranges from popular songs to folk groups and DJs. Join a dance if invited, but do not film people without asking. The events are family-friendly earlier in the evening and rowdier later. If you stay in a residential area, bring earplugs: the music often continues late."
      },
      {
        "h": "Français",
        "p": "Juin est le mois des Santos Populares, les saints populaires : Santo António le 13 juin, São João le 24 et São Pedro le 29. Partout, les quartiers organisent des arraiais, fêtes de rue informelles avec stands, décorations en papier et musique. Ceux de Lisbonne sont célèbres à Alfama, Graça et Bica ; ceux de Porto sont animés à Ribeira et Fontaínhas. L'ambiance est détendue : on mange, on boit, on parle fort et on danse tard.\n\nL'arraial révèle la sociabilité portugaise. Commandez au comptoir, payez et rapportez les verres au stand. Sardines grillées, bifanas et caldo verde sont typiques ; on mange debout ou à de longues tables communes. La musique va des chansons populaires aux groupes folkloriques et aux DJ. Joignez-vous à une danse si on vous invite, mais ne filmez pas les gens sans demander. Les fêtes sont familiales en début de soirée, plus bruyantes ensuite. Si vous logez dans un quartier résidentiel, prévoyez des bouchons d'oreilles : la musique continue tard."
      }
    ],
