    "category": "historia",
    "kicker": "História",
    "title": "O Estado Novo",
    "zh": "新国家体制",
    "titleEn": "The Estado Novo",
    "titleFr": "L'Estado Novo",
    "excerpt": "“新国家”是1933年至1974年统治葡萄牙的威权体制，由经济学教授安东尼奥·德·奥利维拉·萨拉查建立，他于1932年出任总理。1933年宪法确立社团主义国家，实行一党制、受控议会和官方工会。",
    "read": 5,
    "artWord": "censura",
    "sections": [
      {
        "h": "中文",
        "p": "“新国家”是1933年至1974年统治葡萄牙的威权体制，由经济学教授安东尼奥·德·奥利维拉·萨拉查建立，他于1932年出任总理。1933年宪法确立社团主义国家，实行一党制、受控议会和官方工会。政治警察PIDE逮捕并酷刑对待反对者，审查制度则管控报纸、书籍、广播和电影。\n\n在很长一段时间里，葡萄牙贫穷而乡村化，文盲率高，移民众多。1960年代起，经济增长与非洲殖民战争改变了社会，也迫使许多年轻人出国。萨拉查1968年因意外事故下台；继任者马尔塞洛·卡埃塔诺承诺自由化，却保留了政权的核心。"
      },
      {
        "h": "English",
        "p": "The Estado Novo, the authoritarian regime that governed Portugal from 1933 to 1974, was built by António de Oliveira Salazar, a professor of economics who became prime minister in 1932. Its constitution of 1933 set up a corporative state, with a single ruling party, a controlled parliament and official unions. The PIDE, the political police, arrested and tortured opponents, while censorship shaped newspapers, books, radio and films.\n\nFor much of that time Portugal remained poor and rural, with high illiteracy and widespread emigration. From the 1960s economic growth and the colonial war in Africa changed society and pushed many young people abroad. Salazar fell from power in 1968 after an accident; his successor, Marcelo Caetano, promised liberalisation but kept the regime's core."
      },
      {
        "h": "Français",
        "p": "L'Estado Novo, le régime autoritaire qui gouverna le Portugal de 1933 à 1974, fut l'œuvre d'António de Oliveira Salazar, professeur d'économie devenu président du Conseil en 1932. Sa constitution de 1933 instaura un État corporatif, avec un parti unique, un parlement contrôlé et des syndicats officiels. La PIDE, police politique, arrêtait et torturait les opposants, tandis que la censure encadrait journaux, livres, radio et films.\n\nPendant longtemps, le Portugal resta pauvre et rural, avec un fort analphabétisme et une émigration massive. À partir des années 1960, la croissance économique et la guerre coloniale en Afrique transformèrent la société et poussèrent beaucoup de jeunes à l'étranger. Salazar quitta le pouvoir en 1968 après un accident ; son successeur, Marcelo Caetano, promit une libéralisation mais conserva l'essentiel du régime."
      }
    ],
