    "id": "c073",
    "category": "religiao",
    "kicker": "Religião e romarias",
    "title": "A Semana Santa e as procissões",
    "zh": "圣周与游行",
    "titleEn": "Holy Week and Its Processions",
    "titleFr": "La Semaine sainte et ses processions",
    "excerpt": "圣周是复活节前的一周，也是葡萄牙天主教一年中最密集的时段。在许多城镇，善会成员抬着沉重的基督像和圣母像穿过街道，队伍中有忏悔者、蜡烛和演奏缓慢进行曲的乐队。“苦路游行”纪念耶稣背负十字架的十四",
    "read": 4,
    "artWord": "procissão",
    "sections": [
      {
        "h": "中文",
        "p": "圣周是复活节前的一周，也是葡萄牙天主教一年中最密集的时段。在许多城镇，善会成员抬着沉重的基督像和圣母像穿过街道，队伍中有忏悔者、蜡烛和演奏缓慢进行曲的乐队。“苦路游行”纪念耶稣背负十字架的十四处；圣周五夜间的“埋葬主”游行重现安葬，人群静默，手持火把。\n\n北部的布拉加最为著名，其圣周记载可追溯至十六世纪。圣周四夜间，“Ecce Homo”（“看，这个人”）游行把祈祷与戏剧结合，赤脚的“法里科科斯”身穿深色带帽长袍，举着火把走过巴洛克街巷。里斯本、波尔图、奥比杜什和许多村庄各有传统，有花毯、哀歌和守夜的火堆。对信徒而言，这一周在圣周五的静默与复活前夕的喜悦中结束。"
      },
      {
        "h": "English",
        "p": "Holy Week, the week before Easter, is the most intense period of the Catholic year in Portugal. In many towns confraternities carry heavy images of Christ and Our Lady through the streets, accompanied by penitents, candles and bands playing slow marches. The processions of the Passos recall the stations of the Cross; on Good Friday night the Entierro do Senhor re-enacts the burial, with a silent, torchlit crowd.\n\nBraga, in the north, holds the best-known celebrations, documented since the sixteenth century. On Holy Thursday night the Ecce Homo procession mixes prayer with theatre, and barefoot farricocos in dark hooded robes carry torches through the baroque streets. Lisbon, Porto, Óbidos and many villages have their own traditions, with flower carpets, mourning chants and watch fires. For believers the week ends in the silence of Good Friday and the joy of the Easter vigil."
      },
      {
        "h": "Français",
        "p": "La Semaine sainte, qui précède Pâques, est la période la plus intense de l'année catholique au Portugal. Dans beaucoup de villes, des confréries portent de lourdes images du Christ et de la Vierge, entourées de pénitents, de cierges et de fanfares jouant des marches lentes. Les processions des Passos rappellent le chemin de croix ; le soir du Vendredi saint, l'Enterro do Senhor reconstitue la mise au tombeau, dans un silence de torches.\n\nBraga, dans le nord, organise les célébrations les plus connues, attestées depuis le XVIe siècle. Le jeudi saint au soir, la procession de l'Ecce Homo mêle prière et théâtre, et des farricocos pieds nus, en robes sombres à capuche, portent des torches dans les rues baroques. Lisbonne, Porto, Óbidos et bien des villages ont leurs propres traditions : tapis de fleurs, chants de deuil et feux de veille. Pour les croyants, elle s'achève dans le silence du Vendredi saint et la joie de la veillée pascale."
      }
    ],
