    "title": "A Consoada e o Natal português",
    "zh": "葡萄牙的圣诞夜与圣诞节",
    "titleEn": "Consoada and the Portuguese Christmas",
    "titleFr": "La Consoada et Noël au Portugal",
    "excerpt": "葡萄牙的圣诞节以平安夜为中心，即“consoada”，家人聚在一起吃一顿较晚的晚餐。桌上通常有鳕鱼配土豆、卷心菜和橄榄油，随后是炸面包片、炸面点、炸油饼和米布丁。有些地区晚餐较清淡，也有些地方",
    "read": 3,
    "artWord": "consoada",
    "sections": [
      {
        "h": "中文",
        "p": "葡萄牙的圣诞节以平安夜为中心，即“consoada”，家人聚在一起吃一顿较晚的晚餐。桌上通常有鳕鱼配土豆、卷心菜和橄榄油，随后是炸面包片、炸面点、炸油饼和米布丁。有些地区晚餐较清淡，也有些地方吃章鱼或羊肉。饭后许多家庭去参加“公鸡弥撒”，即子夜弥撒，不过如今多数堂区改在傍晚举行。\n\n在许多家庭里，圣诞马槽比圣诞树更重要，一些城镇还搭建大型公共马槽。传统上礼物由圣婴耶稣带来，而不是圣诞老人；许多家庭仍在晚饭后拆礼物，或留到主显节吃“国王蛋糕”时再拆。蛋糕里藏着一颗蚕豆和一件小礼物：吃到蚕豆的人要买下一个蛋糕。节期以元月初的“雅内拉斯”结束，人们成群结队挨家挨户唱歌。"
      },
      {
        "h": "English",
        "p": "Christmas in Portugal centres on Christmas Eve, the consoada, when families gather for a late supper. The table usually carries bacalhau cooked with potatoes, cabbage and olive oil, followed by rabanadas, filhoses, sonhos and arroz doce. In some regions the meal is lighter, and in others it includes octopus or lamb. After dinner many families go to the Missa do Galo, the midnight Mass, though most parishes now celebrate it early in the evening.\n\nThe presépio, the nativity scene, matters more than the tree in many homes, and some towns build large public cribs. Gifts were traditionally brought by the Menino Jesus rather than by Santa Claus, and many families still open them after supper or on Epiphany, when the bolo-rei is eaten. The cake hides a broad bean and a small gift: whoever finds the bean buys the next one. The season ends with the Janeiras, groups singing from door to door in January."
      },
      {
        "h": "Français",
        "p": "Noël au Portugal est centré sur la veille, la consoada, où les familles se réunissent pour un dîner tardif. La table porte du bacalhau cuit avec pommes de terre, chou et huile d'olive, puis des rabanadas, filhoses, sonhos et un riz au lait. Ailleurs, le repas est plus léger, ou comprend du poulpe ou de l'agneau. Après dîner, beaucoup vont à la Missa do Galo, la messe de minuit, désormais célébrée plus tôt dans la plupart des paroisses.\n\nLa crèche, le presépio, compte plus que le sapin dans bien des foyers, et certaines villes installent de grandes crèches publiques. Les cadeaux venaient traditionnellement de l'Enfant Jésus plutôt que du Père Noël, et beaucoup les ouvrent après le repas ou à l'Épiphanie, quand on mange le bolo-rei. Ce gâteau cache une fève et un petit cadeau : qui trouve la fève achète le suivant. La saison s'achève avec les Janeiras, des groupes chantant de porte en porte en janvier."
      }
    ],
