    "id": "c075",
    "category": "religiao",
    "kicker": "Religião e romarias",
    "title": "A Páscoa e o compasso pascal",
    "zh": "复活节与“复活节走访”",
    "titleEn": "Easter and the Compasso",
    "titleFr": "Pâques et le compasso",
    "excerpt": "复活节星期日是钟声、家庭午餐的日子，在许多堂区还有“compasso pascal”（复活节走访）。神父带领一支小队伍，抬着华盖下的圣体挨家挨户祝福教友的住所；一家人常在门口等候，有时还备好桌",
    "read": 3,
    "artWord": "aleluia",
    "sections": [
      {
        "h": "中文",
        "p": "复活节星期日是钟声、家庭午餐的日子，在许多堂区还有“compasso pascal”（复活节走访）。神父带领一支小队伍，抬着华盖下的圣体挨家挨户祝福教友的住所；一家人常在门口等候，有时还备好桌子迎接。这一习俗各地不同，但在北部仍是一年中最令人期待的时刻之一。\n\n复活节餐桌上有“folar”，一种面包：北方做法是咸的，加入肉类；南方则是甜的，上面装饰着整只鸡蛋。教父母传统上要送教子女folar。杏仁、海绵蛋糕和羊肉也会出现。有些村庄会焚烧或击打犹大像，这一习俗带有前基督教的痕迹。周六夜间的复活节守夜礼以祝圣火与水开始，四旬期沉寂的“阿肋路亚”重新回到礼仪中。"
      },
      {
        "h": "English",
        "p": "Easter Sunday is a day of bells, family lunches and, in many parishes, the compasso pascal. A small procession led by the priest carries the Blessed Sacrament under a canopy from house to house, blessing the homes of the parish; families wait at the door, often with a table prepared for the visit. The custom varies from place to place, but in the north it remains one of the most awaited moments of the year.\n\nThe Easter table features folar, a bread that is savoury and enriched with meat in the north, and sweet and decorated with whole eggs in the south. Godparents traditionally give folar to their godchildren. Almonds, pão-de-ló and lamb also appear. In some villages an effigy of Judas is burned or beaten, a custom with pre-Christian echoes. The vigil on Saturday night, with the blessing of fire and water, opens the feast, and the alleluia returns to the liturgy."
      },
      {
        "h": "Français",
        "p": "Le dimanche de Pâques est un jour de cloches, de déjeuners en famille et, dans beaucoup de paroisses, de compasso pascal. Une petite procession conduite par le prêtre porte le Saint-Sacrement sous un dais de maison en maison, bénissant les foyers ; les familles attendent à la porte, parfois devant une table préparée. La coutume varie selon les lieux, mais dans le nord elle reste l'un des moments les plus attendus de l'année.\n\nLa table pascale accueille le folar, un pain salé et enrichi de viande dans le nord, sucré et décoré d'œufs entiers dans le sud. Les parrains et marraines offrent traditionnellement le folar à leurs filleuls. Amandes, pão-de-ló et agneau figurent aussi au menu. Dans certains villages, on brûle ou frappe une effigie de Judas, coutume aux échos préchrétiens. La veillée du samedi soir, avec la bénédiction du feu et de l'eau, ouvre la fête, et l'alleluia revient dans la liturgie."
      }
    ],
