    "id": "c077",
    "category": "religiao",
    "kicker": "Religião e romarias",
    "title": "Romarias e festas do orago",
    "zh": "朝圣节与主保圣人节",
    "titleEn": "Romarias and Patron-Saint Festivals",
    "titleFr": "Romarias et fêtes du saint patron",
    "excerpt": "几乎每个葡萄牙堂区都有自己的主保圣人，即“orago”，以及相应的节庆日。主保节由“mordomo”（主事人）或委员会筹办，往往提前数月准备，可持续数天。活动通常把宗教游行与集市、铜管乐队、烟",
    "read": 4,
    "artWord": "orago",
    "sections": [
      {
        "h": "中文",
        "p": "几乎每个葡萄牙堂区都有自己的主保圣人，即“orago”，以及相应的节庆日。主保节由“mordomo”（主事人）或委员会筹办，往往提前数月准备，可持续数天。活动通常把宗教游行与集市、铜管乐队、烟花和“供品拍卖”结合起来：人们竞买蛋糕、篮子和牲畜，为教堂或小礼拜堂筹款。\n\n“romaria”一词原指前往圣地的旅程，有些聚会能吸引远道而来的朝圣者。维亚纳堡在八月纪念“痛苦圣母”，有船只游行和巨大的花拱；拉梅古在九月登上“救援圣母”圣所；托马尔每四年举办一次“托盘节”，年轻女子头顶装满面包和鲜花的大托盘。许多移居国外的葡萄牙人常围绕这些日期安排夏季休假。这些节庆形式上是宗教的，功能上却是社会的。"
      },
      {
        "h": "English",
        "p": "Almost every Portuguese parish has a patron saint, the orago, and a feast day. The festa do orago is organised by a mordomo or a commission, often months in advance, and can last several days. The programme usually combines a religious procession with a fair, a brass band, fireworks and an auction of offerings, where cakes, baskets and animals are sold to raise money for the church.\n\nThe word romaria first meant a journey to a shrine, and some gatherings draw pilgrims from far away. Viana do Castelo honours Nossa Senhora da Agonia in August with a procession of boats and huge floral arches; Lamego climbs to Nossa Senhora dos Remédios in September; Tomar holds the Festa dos Tabuleiros, with trays of bread and flowers carried by young women, every four years. Emigrants plan their summer holidays around these dates. Religious in form and social in function, the festivals renew ties between families and villages."
      },
      {
        "h": "Français",
        "p": "Presque chaque paroisse a son saint patron, l'orago, et sa fête. La festa do orago est organisée par un mordomo ou une commission, souvent des mois à l'avance, et dure plusieurs jours. Le programme associe une procession religieuse à une foire, une fanfare, des feux d'artifice et une vente aux enchères d'offrandes, où gâteaux, paniers et animaux sont vendus au profit de l'église.\n\nLe mot romaria désignait d'abord un voyage vers un sanctuaire, et certaines fêtes attirent des pèlerins de loin. Viana do Castelo honore Nossa Senhora da Agonia en août, avec une procession de bateaux et d'immenses arcs fleuris ; Lamego monte vers Nossa Senhora dos Remédios en septembre ; Tomar organise tous les quatre ans la Festa dos Tabuleiros, avec des plateaux de pain et de fleurs portés par des jeunes filles. Les émigrés calent souvent leurs vacances sur ces dates. Religieuses par la forme, sociales par la fonction, elles renouent les liens entre familles et villages."
      }
    ],
    "tips": []
