    "category": "religiao",
    "kicker": "Religião e romarias",
    "title": "Herança judaica e muçulmana",
    "zh": "犹太与穆斯林遗产",
    "titleEn": "Jewish and Muslim Heritage",
    "titleFr": "Héritage juif et musulman",
    "excerpt": "葡萄牙的宗教过去并不只有基督教。自711年起，穆斯林统治了大部分领土，直到十三世纪，留下城堡、浴场，并在语言中刻下深深的印记：açúcar（糖）、alfaiate（裁缝）、oxalá（但愿）等",
    "read": 5,
    "artWord": "memória",
    "sections": [
      {
        "h": "中文",
        "p": "葡萄牙的宗教过去并不只有基督教。自711年起，穆斯林统治了大部分领土，直到十三世纪，留下城堡、浴场，并在语言中刻下深深的印记：açúcar（糖）、alfaiate（裁缝）、oxalá（但愿）等词来自阿拉伯语，许多地名以al-开头。里斯本的莫拉里亚和阿尔法玛保留着摩尔城市的记忆，梅尔图拉的教堂至今仍建在一座清真寺的旧址上。\n\n犹太社群曾生活在各中世纪城镇的“judiarias”（犹太区）里。1492年西班牙驱逐犹太人后，许多人越过边境；但1497年国王曼努埃尔一世强迫他们改宗，并驱逐拒绝者。1536年建立的宗教裁判所世代迫害“新基督徒”；1506年里斯本的一场屠杀杀害了数百甚至数千名改宗者。今天，托马尔的犹太会堂已成为博物馆，贝尔蒙特仍有一个秘密犹太教徒后裔社群。"
      },
      {
        "h": "English",
        "p": "Portugal's religious past is not only Christian. Muslims ruled much of the territory from 711 until the thirteenth century, leaving castles, baths and a deep mark on the language: açúcar, alfaiate and oxalá come from Arabic, and many place names begin with al-. Lisbon's Mouraria and Alfama keep the memory of the Moorish city, and the church of Mértola still stands on the site of a mosque.\n\nJewish communities lived in medieval towns, in quarters known as judiarias. After the expulsion of the Jews from Spain in 1492 many crossed the border, but in 1497 King Manuel I forced their conversion and expelled those who refused. The Inquisition, established in 1536, persecuted the cristãos-novos for generations, and a Lisbon massacre in 1506 killed hundreds, perhaps thousands, of converts. Today Tomar's synagogue is a museum, and Belmonte keeps a community of crypto-Jewish descent."
      },
      {
        "h": "Français",
        "p": "Le passé religieux du Portugal n'est pas seulement chrétien. Les musulmans ont gouverné une grande partie du territoire de 711 au XIIIe siècle, laissant châteaux, bains et une empreinte profonde sur la langue : açúcar, alfaiate ou oxalá viennent de l'arabe, et beaucoup de toponymes commencent par al-. La Mouraria et l'Alfama de Lisbonne gardent la mémoire de la ville maure, et l'église de Mértola occupe toujours le site d'une mosquée.\n\nDes communautés juives vivaient dans les villes médiévales, dans des quartiers appelés judiarias. Après l'expulsion des juifs d'Espagne en 1492, beaucoup passèrent la frontière, mais en 1497 le roi Manuel Ier força leur conversion et expulsa ceux qui refusaient. L'Inquisition, établie en 1536, persécuta les cristãos-novos pendant des générations, et un massacre à Lisbonne en 1506 tua des centaines, peut-être des milliers, de convertis. Aujourd'hui, la synagogue de Tomar est un musée, et Belmonte garde une communauté d'origine crypto-juive."
      }
    ],
    "tips": []
