    "id": "c083",
    "category": "futebol",
    "kicker": "Futebol",
    "title": "O FC Porto e o Norte",
    "zh": "波尔图与北方",
    "titleEn": "FC Porto and the North",
    "titleFr": "Le FC Porto et le Nord",
    "excerpt": "波尔图足球俱乐部成立于1893年，是葡萄牙北方的大俱乐部。球迷称它为“龙”，称这座城市为“不可征服之城”。2003年，巨龙球场启用，取代了安塔斯球场。1987年欧洲冠军杯和2004年欧洲冠军联",
    "read": 4,
    "artWord": "dragão",
    "sections": [
      {
        "h": "中文",
        "p": "波尔图足球俱乐部成立于1893年，是葡萄牙北方的大俱乐部。球迷称它为“龙”，称这座城市为“不可征服之城”。2003年，巨龙球场启用，取代了安塔斯球场。1987年欧洲冠军杯和2004年欧洲冠军联赛的胜利，让波尔图在欧洲享有声誉；1982年至2024年，平托·达科斯塔长期担任主席，以延续性和球探体系为核心。\n\n在社会层面，波尔图代表的不只是奖杯。在一个常被指责只看向里斯本的国家里，这家俱乐部给北方一个全国舞台和一种自豪的语言。它的球迷分布在工业城镇、移民社群和家庭传统中。波尔图也说明足球如何组织一座城市的身份：球场、蓝色球衣，以及咖啡馆里周一的讨论。它既是企业，也是政治角色，但对许多人来说，它仍是让地区认出自己的地方。"
      },
      {
        "h": "English",
        "p": "Futebol Clube do Porto was founded in 1893 and has long been the great club of northern Portugal. Supporters call it the Dragões and the city the Invicta. The Estádio do Dragão opened in 2003, replacing the old Antas. Porto's European Cup in 1987 and Champions League in 2004 made it a reference beyond Portugal, and Pinto da Costa's long presidency, from 1982 to 2024, made continuity and scouting central to its model.\n\nSocially, Porto represents more than trophies. In a country often accused of looking only to Lisbon, the club gives the North a national stage and a language of pride. Its fans are found in industrial towns, emigrant communities and family traditions. Porto shows how football can organise a city's identity: the stadium, the blue shirts and the Monday conversations in cafés. It is a business and a political actor, but for many it is first a place where a region recognises itself."
      },
      {
        "h": "Français",
        "p": "Le FC Porto, fondé en 1893, est le grand club du nord du Portugal. Ses supporters l'appellent les Dragões et la ville l'Invicta. Le stade du Dragão a ouvert en 2003, remplaçant les Antas. La Coupe d'Europe de 1987 et la Ligue des champions de 2004 ont fait du club une référence européenne ; la présidence de Pinto da Costa, de 1982 à 2024, a mis la continuité et le recrutement au cœur de son modèle.\n\nSocialement, Porto représente plus que des trophées. Dans un pays souvent accusé de ne regarder que Lisbonne, le club offre au Nord une scène nationale et un langage de fierté. Ses fans se trouvent dans les villes industrielles, les communautés d'émigrés et les traditions familiales. Porto montre comment le football organise l'identité d'une ville : le stade, les maillots bleus et les discussions du lundi au café. C'est une entreprise et un acteur politique, mais c'est d'abord un lieu où une région se reconnaît."
      }
    ],
