    "id": "c087",
    "category": "futebol",
    "kicker": "Futebol",
    "title": "1966: Portugal no mundo",
    "zh": "1966：葡萄牙走向世界",
    "titleEn": "1966: Portugal on the world stage",
    "titleFr": "1966 : le Portugal sur la scène mondiale",
    "excerpt": "1966年英格兰世界杯是葡萄牙首次参赛。球队打进半决赛，最终获得季军，这仍是其世界杯最好成绩。四分之一决赛对朝鲜，葡萄牙在0比3落后时以5比3逆转，尤西比奥独进四球。半决赛他们1比2负于英格兰",
    "read": 5,
    "artWord": "orgulho",
    "sections": [
      {
        "h": "中文",
        "p": "1966年英格兰世界杯是葡萄牙首次参赛。球队打进半决赛，最终获得季军，这仍是其世界杯最好成绩。四分之一决赛对朝鲜，葡萄牙在0比3落后时以5比3逆转，尤西比奥独进四球。半决赛他们1比2负于英格兰，季军赛2比1击败苏联。尤西比奥成为该届最佳射手。\n\n这届赛事给一个贫穷而专制的国家带来现代形象。葡萄牙当时处于萨拉查独裁之下，并在非洲进行殖民战争；政权把球队的成功当作宣传。但这支球队也是帝国的产物，队中有出生在莫桑比克等殖民地的球员。数十年后，记忆仍然双重：为伟大一代自豪，也对这份自豪被政治利用感到不安。对学习者来说，1966年说明足球为何成为葡萄牙人谈论国家认同的少数共同语言之一。"
      },
      {
        "h": "English",
        "p": "The 1966 World Cup in England was Portugal's first. The team reached the semi-finals and finished third, still the country's best World Cup result. In the quarter-final against North Korea, Portugal were 3–0 down and won 5–3, with four goals from Eusébio. They lost 2–1 to England at Wembley, then beat the Soviet Union 2–1 in the third-place match. Eusébio finished as the tournament's top scorer.\n\nThe tournament mattered because it gave a poor, authoritarian country a modern national image. Portugal was living under Salazar's Estado Novo and fighting colonial wars in Africa; the regime used the team's success as propaganda. Yet the team was also a product of empire, with players born in Mozambique and other colonies. Decades later, the memory is still double: pride in a great generation and unease about the political uses of that pride. For learners, 1966 explains why football became one of the few languages in which Portuguese people could speak about the nation."
      },
      {
        "h": "Français",
        "p": "Le Mondial 1966 en Angleterre fut le premier du Portugal. L'équipe a atteint les demi-finales et terminé troisième, son meilleur résultat. En quart de finale contre la Corée du Nord, menée 3-0, elle a gagné 5-3, avec quatre buts d'Eusébio. Elle a perdu 2-1 contre l'Angleterre à Wembley, puis battu l'URSS 2-1 pour la troisième place. Eusébio fut meilleur buteur du tournoi.\n\nCe tournoi a compté : il a donné à un pays pauvre, autoritaire une image nationale moderne. Le Portugal vivait sous l'Estado Novo de Salazar et menait des guerres coloniales ; le régime a utilisé le succès de l'équipe comme propagande. Mais cette équipe était aussi un produit de l'empire, avec des joueurs nés au Mozambique et ailleurs. Des décennies plus tard, le souvenir reste double : fierté pour une génération et malaise face à l'usage politique de cette fierté. Pour l'apprenant, 1966 explique pourquoi le football est devenu une des rares langues pour parler de la nation."
      }
    ],
