    "id": "c088",
    "category": "futebol",
    "kicker": "Futebol",
    "title": "Euro 2004: a festa e a desilusão",
    "zh": "2004年欧洲杯：盛宴与失落",
    "titleEn": "Euro 2004: the party and the disappointment",
    "titleFr": "Euro 2004 : la fête et la déception",
    "excerpt": "葡萄牙主办了2004年欧洲杯，新建或翻修了十座球场。球队在揭幕战输给希腊，随后击败俄罗斯和西班牙，又在点球大战中淘汰英格兰，半决赛战胜荷兰，进入决赛。在里斯本，希腊凭借查理斯特亚斯的头球以1比",
    "read": 3,
    "artWord": "festa",
    "sections": [
      {
        "h": "中文",
        "p": "葡萄牙主办了2004年欧洲杯，新建或翻修了十座球场。球队在揭幕战输给希腊，随后击败俄罗斯和西班牙，又在点球大战中淘汰英格兰，半决赛战胜荷兰，进入决赛。在里斯本，希腊凭借查理斯特亚斯的头球以1比0获胜。葡萄牙第一次打进大赛决赛，却在主场失利。十九岁的C罗是赛事的一大发现。\n\n这场失利被记作民族创伤，但赛事也改变了日常生活。一个月里，街头挂满旗帜，电视机被搬到咖啡馆和广场，平时很少看球的人也记住了球员的名字。新球场引发关于公共资金的争论，盛会则让葡萄牙感到有能力承办大赛。决赛表明，足球能让一个国家在失望中同样团结。2004年欧洲杯不只关于一场比赛，更关于一个小国如何展示自己在欧洲的位置。"
      },
      {
        "h": "English",
        "p": "Portugal hosted Euro 2004 and built or rebuilt ten stadiums. The team lost its opening match to Greece, then beat Russia and Spain, England on penalties and the Netherlands to reach the final. In Lisbon, Greece won 1–0 with a header from Angelos Charisteas. Portugal reached a major final for the first time, and lost it at home. Cristiano Ronaldo, then nineteen, was one of the revelations.\n\nThe defeat is remembered as a national trauma, but the tournament also changed everyday life. For a month, streets were full of flags, televisions moved into cafés and squares, and people who rarely watched football learned the players' names. The new stadiums provoked debate about public money, while the party gave Portugal a sense of competence as an organiser. The final showed that football can unite a country in disappointment as powerfully as in victory. Euro 2004 is less about one match than about how a small nation performs its place in Europe."
      },
      {
        "h": "Français",
        "p": "Le Portugal a accueilli l'Euro 2004 et bâti ou rénové dix stades. L'équipe a perdu contre la Grèce, puis battu la Russie, l'Espagne, l'Angleterre aux tirs au but et les Pays-Bas jusqu'en finale. À Lisbonne, la Grèce a gagné 1-0 sur une tête de Charisteas. Le Portugal perdait sa première finale majeure, chez lui. Cristiano Ronaldo, dix-neuf ans, fut une révélation.\n\nLa défaite reste un traumatisme, mais le tournoi a changé la vie quotidienne. Pendant un mois, les rues se sont couvertes de drapeaux, les téléviseurs ont gagné les cafés et les places, et des gens qui regardaient rarement le football ont appris les noms. Les stades ont nourri un débat sur l'argent public, tandis que la fête a donné au pays un sentiment de compétence. La finale a montré que le football unit un pays dans la déception autant que dans la victoire. L'Euro 2004 parle moins d'un match que de la place d'une petite nation en Europe."
      }
    ],
    "tips": []
