    "kicker": "Língua e expressões",
    "title": "Desenrascanço: a arte de se desenrascar",
    "zh": "desenrascanço：见招拆招的本事",
    "titleEn": "Desenrascanço: the art of getting by",
    "titleFr": "Le desenrascanço, l'art de se débrouiller",
    "excerpt": "desenrascanço 指手头有什么就用什么、临时摆脱困境的本事。动词 desenrascar-se 有“从纠缠中脱身”的意思，名词强调的是这种才能，而不是具体动作。它是褒义词：Ele t",
    "read": 4,
    "artWord": "desenrasco",
    "sections": [
      {
        "h": "中文",
        "p": "desenrascanço 指手头有什么就用什么、临时摆脱困境的本事。动词 desenrascar-se 有“从纠缠中脱身”的意思，名词强调的是这种才能，而不是具体动作。它是褒义词：Ele tem um desenrascanço incrível 意思是某人总能在计划泡汤时找到办法，常用到胶带、借来的车和一通电话。日常口语中也会说 Desenrasquei-me como pude，意思是我尽力应付过去了。\n\n这个词带着一种矛盾意味，学习者要留意。葡萄牙人欣赏它，把它看作务实和生存能力的证明，尤其在艰难时期；但它也可能为缺乏计划的临时应付开脱。它和巴西的 jeitinho 并不相同：desenrascanço 主要靠有限的条件和一双巧手，jeitinho 往往涉及说服别人或变通规则。用它时带点笑意，别用在正式的职业描述里——那里说 capacidade de resolução 更严肃。"
      },
      {
        "h": "English",
        "p": "Desenrascanço is the ability to get out of a tight spot by improvising with whatever is at hand. The verb desenrascar-se suggests freeing oneself from a tangle; the noun names the talent, not the act. It is a compliment: 'Ele tem um desenrascanço incrível' means someone finds a solution when plans collapse, often with tape, a borrowed car and a phone call. In ordinary speech: 'Desenrasquei-me como pude' — I managed as best I could.\n\nThe word carries an ambivalence learners should notice. Portuguese admire it as proof of practicality and survival, especially in hard times, but it can also excuse improvisation where planning was needed. It is not Brazilian jeitinho: desenrascanço relies on scarce means and quick hands, while jeitinho often involves persuading people or bending a rule. Use it with a smile, and avoid it in formal descriptions of professional work, where 'capacidade de resolução' sounds more serious."
      },
      {
        "h": "Français",
        "p": "Le desenrascanço est la capacité de se sortir d'une situation délicate en improvisant avec les moyens du bord. Le verbe desenrascar-se évoque l'idée de se dégager d'un embrouillement ; le nom désigne le talent, non l'acte. C'est un compliment : « Ele tem um desenrascanço incrível » signifie que quelqu'un trouve une solution quand les plans s'effondrent, souvent avec du ruban adhésif, une voiture prêtée et un appel. Dans la langue courante : « Desenrasquei-me como pude », je me suis débrouillé comme j'ai pu.\n\nLe mot est ambigu. Les Portugais l'admirent comme une preuve d'esprit pratique et de survie, surtout en période difficile, mais il peut aussi excuser l'improvisation là où il fallait planifier. Ce n'est pas le jeitinho brésilien : le desenrascanço repose sur des moyens limités et l'habileté manuelle, tandis que le jeitinho passe souvent par la persuasion ou un accommodement avec la règle. Employez-le avec le sourire, et évitez-le dans une description professionnelle formelle, où « capacidade de resolução » sonne plus sérieux."
      }
    ],
    "tips": []
