    "id": "c093",
    "category": "lingua",
    "kicker": "Língua e expressões",
    "title": "Jeitinho: o jeito brasileiro de resolver",
    "zh": "jeitinho：巴西人的变通之道",
    "titleEn": "Jeitinho: the Brazilian way around",
    "titleFr": "Le jeitinho, la débrouille à la brésilienne",
    "excerpt": "jeitinho 是 jeito（方式、窍门）的指小词，在巴西指一种小巧聪明的变通，让问题消失。Dá um jeitinho nisso（想个办法把这事办了）可能是找到一张没人知道存在的表格、",
    "read": 4,
    "artWord": "jeito",
    "sections": [
      {
        "h": "中文",
        "p": "jeitinho 是 jeito（方式、窍门）的指小词，在巴西指一种小巧聪明的变通，让问题消失。Dá um jeitinho nisso（想个办法把这事办了）可能是找到一张没人知道存在的表格、托个人情，或说服办事员通融一下规则。它最好的一面是创造力和人情味，最坏的一面则滑向特权：有门路的人总能找到 jeitinho，而别人只能排队。\n\n巴西人说起 jeitinho brasileiro 时既自豪又带讽刺，这种含混正是关键。它不简单等于腐败，虽然可能滑向那里；它也不等于葡萄牙的 desenrascanço，后者更多是用有限条件即兴发挥。无害的例子：面包师给一位忘记预订的常客留了个蛋糕。令人不安的例子：司机靠一番话逃掉罚单。学习者应当认识这个词，欣赏前一种，并小心不要赞美后一种。"
      },
      {
        "h": "English",
        "p": "Jeitinho is the diminutive of jeito, 'way' or 'knack', and in Brazil it names a small, clever arrangement that makes a problem disappear. 'Dá um jeitinho nisso' — sort this out somehow — can mean finding an unknown form, asking a favour, or persuading a clerk to bend a rule. At its best it is creativity and warmth; at its worst it shades into privilege, because the person with contacts always finds a jeitinho while others queue.\n\nBrazilians use 'jeitinho brasileiro' with pride and irony at once; the ambiguity is the point. It is not simply corruption, though it can slide there, nor Portuguese desenrascanço, which improvises with scarce means. A harmless example: a baker keeps a cake for a regular who forgot to order. A troubling one: a driver talks his way out of a fine. Learners should recognise the word, enjoy the first kind, and not celebrate the second."
      },
      {
        "h": "Français",
        "p": "Jeitinho est le diminutif de jeito, « façon » ou « tour de main », et au Brésil il désigne un petit arrangement astucieux qui fait disparaître un problème. « Dá um jeitinho nisso » — arrange-moi ça — peut signifier trouver un formulaire inconnu, demander un service ou convaincre un employé d'assouplir une règle. Au meilleur sens, c'est de la créativité et de la chaleur humaine ; au pire, cela glisse vers le privilège, car celui qui a des relations trouve toujours un jeitinho pendant que les autres font la queue.\n\nLes Brésiliens emploient « jeitinho brasileiro » avec fierté et ironie ; l'ambiguïté est le sujet. Ce n'est pas une simple corruption, même si cela y mène, ni le desenrascanço portugais, qui improvise avec peu de moyens. Exemple anodin : un boulanger garde un gâteau pour un habitué qui a oublié sa commande. Exemple gênant : un automobiliste échappe à une amende à force de bagout. L'apprenant doit connaître le mot, apprécier le premier cas et se garder d'admirer le second."
      }
    ],
    "tips": []
