        "h": "中文",
        "p": "欧洲葡语和巴西葡语是同一种语言的两种规范，差别远不止口音。葡萄牙说 autocarro、pequeno-almoço、casa de banho；巴西说 ônibus、café da manhã、banheiro。语法也不同：葡萄牙更爱说 estou a fazer，巴西说 estou fazendo；葡萄牙把宾语代词放在动词后（dou-te um livro），巴西常放在动词前（te dou um livro）。1990年的正字法协议统一了一部分拼写，但 facto 和 fato 仍把两边分开。\n\n历史解释了这种差距。巴西葡语从殖民时期的语言发展而来，吸收原住民和非洲语言的影响，并保留了一些较早的特征；欧洲葡语则朝其他方向演变。两者都不是对方的“败坏”，都有自己的文学、词典和媒体。书面语互通度很高，口语通常也没问题，只是欧洲葡语的元音弱化很重，巴西人一开始可能听不惯。对学习者来说，选一种规范并保持一致，同时学会听懂另一种——巴西人和葡萄牙人都习惯了两种口音。"
